INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (102301, 10046, "2020/07/31 12:00:00", 2, 2, 0.0, 0.0, "アヤネ", 0.0, "2030/12/17 14:59:59", "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 401, 24, 24001);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (102301, 10046, "2020/07/31 12:00:00", 2, 1, 0.0, 2.21, "アヤネ", 0.0, "2030/12/17 14:59:59", "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 402, 24, 24002);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (102301, 10046, "2020/07/31 12:00:00", 2, 2, 0.0, 0.0, "アヤネ", 0.0, "2030/12/17 14:59:59", "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 403, 24, 24003);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (192201, 10046, "2020/07/31 12:00:00", 1, 2, 0.0, 1.99, "アサヒ", 0.0, "2030/12/17 14:59:59", "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 701, 24, 24004);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (192201, 10046, "2020/07/31 12:00:00", 2, 1, 0.0, 2.21, "アサヒ", 0.0, "2030/12/17 14:59:59", "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 702, 24, 24005);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (192201, 10046, "2020/07/31 12:00:00", 1, 2, 0.0, 3.33, "アサヒ", 0.0, "2030/12/17 14:59:59", "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 703, 24, 24006);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (192301, 10046, "2020/07/31 12:00:00", 2, 2, 0.0, 0.0, "部員３", 0.0, "2030/12/17 14:59:59", "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 801, 24, 24007);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (192301, 10046, "2020/07/31 12:00:00", 2, 1, 0.0, 2.68, "部員３", 0.0, "2030/12/17 14:59:59", "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 802, 24, 24008);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (192301, 10046, "2020/07/31 12:00:00", 2, 2, 0.0, 0.0, "部員３", 0.0, "2030/12/17 14:59:59", "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 803, 24, 24009);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (192501, 10046, "2020/07/31 12:00:00", 1, 1, 0.0, 0.0, "", 0.0, "2030/12/17 14:59:59", "やった！", 501, 24, 24010);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (192501, 10046, "2020/07/31 12:00:00", 1, 1, 0.0, 0.0, "", 0.0, "2030/12/17 14:59:59", "勝ったよ！", 502, 24, 24011);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (192501, 10046, "2020/07/31 12:00:00", 1, 1, 0.0, 0.0, "", 0.0, "2030/12/17 14:59:59", "いい調子！", 503, 24, 24012);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (113501, 10046, "2020/07/31 12:00:00", 2, 6, 0.0, 5.33, "ミサト", 0.0, "2030/12/17 14:59:59", "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 111, 24, 24013);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (113501, 10046, "2020/07/31 12:00:00", 2, 1, 0.0, 6.85, "ミサト", 0.0, "2030/12/17 14:59:59", "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 112, 24, 24014);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (113501, 10046, "2020/07/31 12:00:00", 2, 1, 0.0, 3.0, "ミサト", 0.0, "2030/12/17 14:59:59", "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 113, 24, 24015);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (192401, 10046, "2020/07/31 12:00:00", 2, 1, 0.0, 6.11, "ダイチ", 0.0, "2030/12/17 14:59:59", "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 611, 24, 24016);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (192401, 10046, "2020/07/31 12:00:00", 2, 1, 0.0, 6.75, "ダイチ", 0.0, "2030/12/17 14:59:59", "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 612, 24, 24017);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (192401, 10046, "2020/07/31 12:00:00", 2, 2, 0.0, 0.0, "ダイチ", 0.0, "2030/12/17 14:59:59", "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 613, 24, 24018);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (113401, 10046, "2020/07/31 12:00:00", 1, 2, 0.0, 4.52, "ハツネ", 0.0, "2030/12/17 14:59:59", "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 211, 24, 24019);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (113401, 10046, "2020/07/31 12:00:00", 1, 2, 0.0, 3.89, "ハツネ", 0.0, "2030/12/17 14:59:59", "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 212, 24, 24020);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (113401, 10046, "2020/07/31 12:00:00", 2, 1, 0.0, 13.49, "ハツネ", 0.0, "2030/12/17 14:59:59", "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 213, 24, 24021);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (106501, 10046, "2020/07/31 12:00:00", 2, 1, 0.0, 3.17, "カヤ", 0.0, "2030/12/17 14:59:59", "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 311, 24, 24022);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (106501, 10046, "2020/07/31 12:00:00", 2, 1, 0.0, 4.42, "カヤ", 0.0, "2030/12/17 14:59:59", "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 312, 24, 24023);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (106501, 10046, "2020/07/31 12:00:00", 1, 6, 0.0, 2.89, "カヤ", 0.0, "2030/12/17 14:59:59", "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 313, 24, 24024);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (102301, 10046, "2020/07/31 12:00:00", 3, 4, 0.0, 3.71, "アヤネ", 0.0, "2030/12/17 14:59:59", "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 421, 24, 24025);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (192201, 10046, "2020/07/31 12:00:00", 1, 2, 0.0, 5.1, "アサヒ", 0.0, "2030/12/17 14:59:59", "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 721, 24, 24026);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (192301, 10046, "2020/07/31 12:00:00", 3, 1, 0.0, 4.34, "部員３", 0.0, "2030/12/17 14:59:59", "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 821, 24, 24027);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (192501, 10046, "2020/07/31 12:00:00", 1, 1, 0.0, 0.0, "", 0.0, "2030/12/17 14:59:59", "いい勝負だったよ\nまたやろうね", 521, 24, 24028);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (113501, 10046, "2020/07/31 12:00:00", 2, 1, -360.0, 5.62, "ミサト", 0.0, "2030/12/17 14:59:59", "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", 101, 24, 24029);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (113501, 10046, "2020/07/31 12:00:00", 2, 1, -360.0, 9.58, "ミサト", 0.0, "2030/12/17 14:59:59", "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", 102, 24, 24030);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (113501, 10046, "2020/07/31 12:00:00", 2, 2, -360.0, 0.0, "ミサト", 0.0, "2030/12/17 14:59:59", "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", 103, 24, 24031);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (113501, 10046, "2020/07/31 12:00:00", 1, 2, -360.0, 9.13, "ミサト", 0.0, "2030/12/17 14:59:59", "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", 104, 24, 24032);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (113501, 10046, "2020/07/31 12:00:00", 2, 1, -360.0, 8.27, "ミサト", 0.0, "2030/12/17 14:59:59", "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", 105, 24, 24033);
